import React, { useState } from "react";
import "./Homepage.css";
const images = [
  'https://via.placeholder.com/800x400/FF0000/FFFFFF?text=Image+1',
  'https://via.placeholder.com/800x400/00FF00/FFFFFF?text=Image+2',
  'https://via.placeholder.com/800x400/0000FF/FFFFFF?text=Image+3',
  'https://via.placeholder.com/800x400/FFFF00/FFFFFF?text=Image+4',
];


const Homepage = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  console.log(currentIndex)

  const goToPrevious = () => {
    const isFirstSlide = currentIndex === 0;
    const newIndex = isFirstSlide ? images.length - 1 : currentIndex - 1;
    setCurrentIndex(newIndex);
  };

  const goToNext = () => {
    const isLastSlide = currentIndex === images.length - 1;
    const newIndex = isLastSlide ? 0 : currentIndex + 1;
    setCurrentIndex(newIndex);
  };

  const arrowLeftDisplay = currentIndex === 0 ? "none" : "block";
  const arrowRightDisplay = currentIndex === images.length - 1 ? "none" : "block";

  return (
    <div className="gallery">
      <button onClick={goToPrevious} className="arrow left-arrow" style={{display: arrowLeftDisplay}}> 
        ❮
      </button>

      <div className="slider">
        <div className="slider-inner" style={{transform: `translateX(-${currentIndex * 100}%)`}}>
          {images.map((image,index) => (
            <div className="slide" key={index}>
              <img src={image} className="image"/>
            </div>
          ))}
        </div>
      </div>




      <button onClick={goToNext} className="arrow right-arrow" style={{display: arrowRightDisplay}}>
        ❯
      </button>
    </div>
  )


};

export default Homepage;
